import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total } from './src/total.js';
test('sum contract', () => {
  assert.equal(total([]), 0);
  assert.equal(total([2, 3, 4]), 9);
  assert.equal(total([-3, 1]), -2);
  const input = [4, 2]; total(input); assert.deepEqual(input, [4, 2]);
});
